scripts.global:
function OnLoad()
  local z = GameConfig.table.zone
  return {
    effects = {
      { type = "define_zone", id = "table", minX = z.minX, minY = z.minY, maxX = z.maxX, maxY = z.maxY },
    },
  }
end

function HandleIntent(intent)
  local t = intent.type
  local playerId = intent.playerId

  if t == "join" then
    local name = ""
    if intent.payload and intent.payload.displayName then
      name = intent.payload.displayName
    end
    return {
      ok = true,
      effects = {
        {
          type = "ensure_player",
          playerId = playerId,
          displayName = name,
        },
        {
          type = "broadcast",
          message = playerId .. " joined",
        },
      },
    }
  end

  if t == "start_game" then
    local sp = GameConfig.board.spawn
    return {
      ok = true,
      effects = {
        {
          type = "spawn_object",
          objectKind = "table_board",
          x = sp.x,
          y = sp.y,
          rotation = GameConfig.board.rotation,
          layer = GameConfig.board.layer,
          tags = { "board" },
        },
        { type = "set_phase", phase = "playing" },
        { type = "set_turn_player", playerId = playerId },
        { type = "broadcast", message = "Game started" },
      },
    }
  end

  if t == "custom" then
    local msg = "custom"
    if intent.payload and intent.payload.message then
      msg = tostring(intent.payload.message)
    end
    return {
      ok = true,
      effects = {
        { type = "broadcast", message = msg },
      },
    }
  end

  return { ok = false, reason = "unknown intent: " .. tostring(t) }
end
